import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
# ---------------------------------------------------------------------------
# Hand-authored PTX GEMM kernel.
#
# Computes C(M,N) = A(M,K) @ B(K,N), all tensors row-major / contiguous
# float32.  Tiling: 32x32 output tile per CTA, using an 8x8 = 64 thread
# block.  Each thread now computes a 4x4 register-blocked sub-tile of the
# 32x32 output tile (up from 2x2), so each value loaded from shared memory
# is reused across 4 output elements instead of 2, doubling arithmetic
# intensity per shared-memory load relative to the previous 2x2-blocked
# kernel.  The global -> shared staging loads are vectorized with
# ld.global.v4 / st.shared.v4 (16B) transfers, and the K=32 reduction is
# still performed as a single fully-resident shared-memory tile (no K-loop
# tiling needed since K == 32 exactly).
#
# Requires M % 32 == 0, N % 32 == 0, and K == 32 (true for the target
# problem: M = 32768, K = 32, N = 32768).
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64
.visible .entry gemm_kernel(
    .param .u64 gemm_kernel_param_A,
    .param .u64 gemm_kernel_param_B,
    .param .u64 gemm_kernel_param_C,
    .param .u32 gemm_kernel_param_M,
    .param .u32 gemm_kernel_param_N,
    .param .u32 gemm_kernel_param_K
)
{
    .reg .b32       %r<55>;
    .reg .b64       %rd<30>;
    .reg .f32       %f<30>;
    .reg .pred      %p<2>;
    .shared .align 16 .b8 sA[4608];   // 32 x 36 floats (col-padded to avoid bank conflicts, 16B-aligned stride)
    .shared .align 16 .b8 sB[4096];   // 32 x 32 floats
    ld.param.u64 %rd1, [gemm_kernel_param_A];
    ld.param.u64 %rd2, [gemm_kernel_param_B];
    ld.param.u64 %rd3, [gemm_kernel_param_C];
    ld.param.u32 %r1,  [gemm_kernel_param_M];
    ld.param.u32 %r2,  [gemm_kernel_param_N];
    ld.param.u32 %r3,  [gemm_kernel_param_K];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r4, %ctaid.x;   // bn : N-tile index
    mov.u32 %r5, %ctaid.y;   // bm : M-tile index
    mov.u32 %r6, %tid.x;     // tx : 0..7
    mov.u32 %r7, %tid.y;     // ty : 0..7
    // linear thread id, 0..63
    shl.b32 %r8, %r7, 3;
    add.s32 %r8, %r8, %r6;
    // base_idx = tid*16 (each thread stages 16 contiguous elements)
    shl.b32 %r9, %r8, 4;
    shr.u32 %r10, %r9, 5;     // i_or_k = base_idx / 32
    and.b32 %r11, %r9, 31;    // off    = base_idx % 32
    // ---- Stage A tile (32 rows x 32 cols) into shared memory ----
    shl.b32 %r12, %r5, 5;
    add.s32 %r12, %r12, %r10;      // rowA = bm*32 + i_or_k
    shl.b32 %r13, %r12, 5;
    add.s32 %r13, %r13, %r11;      // addrA_elem = rowA*32 + off
    cvt.s64.s32 %rd4, %r13;
    shl.b64 %rd4, %rd4, 2;
    add.s64 %rd5, %rd1, %rd4;      // global A byte address
    mov.u32 %r14, sA;
    mul.lo.s32 %r15, %r10, 144;   // row * 144 (padded stride, 16B-aligned)
    add.s32 %r15, %r14, %r15;
    shl.b32 %r16, %r11, 2;
    add.s32 %r15, %r15, %r16;      // sA store address
    cp.async.cg.shared.global [%r15], [%rd5], 16;
    cp.async.cg.shared.global [%r15+16], [%rd5+16], 16;
    cp.async.cg.shared.global [%r15+32], [%rd5+32], 16;
    cp.async.cg.shared.global [%r15+48], [%rd5+48], 16;
    // ---- Stage B tile (32 rows x 32 cols) into shared memory ----
    shl.b32 %r17, %r4, 5;
    add.s32 %r17, %r17, %r11;      // colB_off_global = bn*32 + off
    cvt.s64.s32 %rd6, %r10;        // rowB_64 (= k index 0..31)
    cvt.s64.s32 %rd7, %r2;         // N_64
    mul.lo.s64 %rd8, %rd6, %rd7;   // rowB*N
    cvt.s64.s32 %rd9, %r17;
    add.s64 %rd10, %rd8, %rd9;
    shl.b64 %rd10, %rd10, 2;
    add.s64 %rd11, %rd2, %rd10;    // global B byte address
    mov.u32 %r18, sB;
    shl.b32 %r19, %r10, 7;
    add.s32 %r19, %r18, %r19;
    add.s32 %r19, %r19, %r16;      // sB store address
    cp.async.cg.shared.global [%r19], [%rd11], 16;
    cp.async.cg.shared.global [%r19+16], [%rd11+16], 16;
    cp.async.cg.shared.global [%r19+32], [%rd11+32], 16;
    cp.async.cg.shared.global [%r19+48], [%rd11+48], 16;
    cp.async.commit_group;
    cp.async.wait_group 0;
    bar.sync 0;
    // ---- Compute-phase address setup (4x4 register blocking) ----
    shl.b32 %r20, %r6, 2;    // c0 = tx*4  (local col within 32-tile)
    shl.b32 %r21, %r7, 2;    // r0 = ty*4  (local row within 32-tile)
    add.s32 %r22, %r21, 0;   // r0
    add.s32 %r23, %r21, 1;   // r1
    add.s32 %r24, %r21, 2;   // r2
    add.s32 %r25, %r21, 3;   // r3
    mul.lo.s32 %r26, %r22, 144;   // row * 144 (padded stride, 16B-aligned)
    add.s32 %r26, %r14, %r26;   // addrA_r0_base
    mul.lo.s32 %r27, %r23, 144;   // row * 144 (padded stride, 16B-aligned)
    add.s32 %r27, %r14, %r27;   // addrA_r1_base
    mul.lo.s32 %r28, %r24, 144;   // row * 144 (padded stride, 16B-aligned)
    add.s32 %r28, %r14, %r28;   // addrA_r2_base
    mul.lo.s32 %r29, %r25, 144;   // row * 144 (padded stride, 16B-aligned)
    add.s32 %r29, %r14, %r29;   // addrA_r3_base
    shl.b32 %r30, %r20, 2;
    add.s32 %r30, %r18, %r30;   // colBase = sB_base + c0*4
    shl.b32 %r32, %r5, 5;       // bm*32
    add.s32 %r33, %r32, %r22;   // row0 (global)
    add.s32 %r34, %r32, %r23;   // row1
    add.s32 %r35, %r32, %r24;   // row2
    add.s32 %r36, %r32, %r25;   // row3
    shl.b32 %r37, %r4, 5;       // bn*32
    add.s32 %r38, %r37, %r20;   // col0 (global)
    add.s32 %r39, %r38, 1;      // col1
    add.s32 %r40, %r38, 2;      // col2
    add.s32 %r41, %r38, 3;      // col3
    mov.f32 %f5,  0f00000000;   // acc00
    mov.f32 %f6,  0f00000000;   // acc01
    mov.f32 %f7,  0f00000000;   // acc02
    mov.f32 %f8,  0f00000000;   // acc03
    mov.f32 %f9,  0f00000000;   // acc10
    mov.f32 %f10, 0f00000000;   // acc11
    mov.f32 %f11, 0f00000000;   // acc12
    mov.f32 %f12, 0f00000000;   // acc13
    mov.f32 %f13, 0f00000000;   // acc20
    mov.f32 %f14, 0f00000000;   // acc21
    mov.f32 %f15, 0f00000000;   // acc22
    mov.f32 %f16, 0f00000000;   // acc23
    mov.f32 %f17, 0f00000000;   // acc30
    mov.f32 %f18, 0f00000000;   // acc31
    mov.f32 %f19, 0f00000000;   // acc32
    mov.f32 %f20, 0f00000000;   // acc33
    ld.shared.f32 %f21, [%r26];
    ld.shared.f32 %f22, [%r27];
    ld.shared.f32 %f23, [%r28];
    ld.shared.f32 %f24, [%r29];
    ld.shared.v4.f32 {%f25,%f26,%f27,%f28}, [%r30];
    fma.rn.f32 %f5,  %f21, %f25, %f5;
