import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX GEMM kernel.
#
# Computes C(M,N) = A(M,K) @ B(K,N), all tensors row-major / contiguous
# float32.  Tiling: 32x32 output tile per CTA (same as before), but now
# the CTA uses a 16x16 = 256 thread block instead of 32x32 = 1024 threads.
# Each thread computes a 2x2 register-blocked sub-tile of the 32x32 output
# tile (thread-level tiling).  This halves the number of shared-memory
# loads issued per CTA per K-step (each shared value loaded from sA/sB is
# now reused across 2 output elements) and increases arithmetic intensity
# per thread (4 FMAs per 4 shared loads instead of 1 FMA per 2 shared
# loads), reducing shared-memory traffic pressure while keeping the same
# fully-unrolled single K-tile structure (K == 32 exactly).
#
# Requires M % 32 == 0, N % 32 == 0, and K == 32 (true for the target
# problem: M = 32768, K = 32, N = 32768).
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64
.visible .entry gemm_kernel(
    .param .u64 gemm_kernel_param_A,
    .param .u64 gemm_kernel_param_B,
    .param .u64 gemm_kernel_param_C,
    .param .u32 gemm_kernel_param_M,
    .param .u32 gemm_kernel_param_N,
    .param .u32 gemm_kernel_param_K
)
{
    .reg .b32       %r<40>;
    .reg .b64       %rd<30>;
    .reg .f32       %f<20>;
    .shared .align 4 .b8 sA[4096];   // 32 x 32 floats
    .shared .align 4 .b8 sB[4096];   // 32 x 32 floats
    ld.param.u64 %rd1, [gemm_kernel_param_A];
    ld.param.u64 %rd2, [gemm_kernel_param_B];
    ld.param.u64 %rd3, [gemm_kernel_param_C];
    ld.param.u32 %r1,  [gemm_kernel_param_M];
    ld.param.u32 %r2,  [gemm_kernel_param_N];
    ld.param.u32 %r3,  [gemm_kernel_param_K];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r4, %ctaid.x;   // bn : N-tile index
    mov.u32 %r5, %ctaid.y;   // bm : M-tile index
    mov.u32 %r6, %tid.x;     // tx : 0..15
