    add.s64 %rd22, %rd3, %rd21;
    st.global.f32 [%rd22], %f1;
    add.s64 %rd20, %rd18, %rd11;
    shl.b64 %rd21, %rd20, 2;
    add.s64 %rd22, %rd3, %rd21;
    st.global.f32 [%rd22], %f2;
    add.s64 %rd20, %rd19, %rd10;
    shl.b64 %rd21, %rd20, 2;
    add.s64 %rd22, %rd3, %rd21;
    st.global.f32 [%rd22], %f3;
    add.s64 %rd20, %rd19, %rd11;
    shl.b64 %rd21, %rd20, 2;
    add.s64 %rd22, %rd3, %rd21;
    st.global.f32 [%rd22], %f4;
    ret;
}
"""

_KERNEL_NAME = "gemm_kernel"
_TILE = 32

_module_singleton = None


def _get_module():
    global _module_singleton
    if _module_singleton is None:
        _module_singleton = PtxModule(PTX_SOURCE)
    return _module_singleton


def validate_generated_code():
    """Look up the kernel entry point to make sure the PTX module is valid."""
    module = _get_module()
    fn = module.function(_KERNEL_NAME)
    assert fn is not None, f"Entry point '{_KERNEL_NAME}' not found in PTX module"
    return fn


class ModelNew(nn.Module):
    """
    Performs C = A @ B using a hand-written PTX tiled GEMM kernel executed
    through cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self) -> None:
        super().__init__()
        self._module = None

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "A and B must be CUDA tensors"
        assert A.dim() == 2 and B.dim() == 2, "A and B must be 2D"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Expect float32 tensors"

        A_c = A.contiguous()
        B_c = B.contiguous()

        M = A_c.shape[0]
        K = A_c.shape[1]
        N = B_c.shape[1]
        assert B_c.shape[0] == K, "Inner dimensions of A and B must match"
        assert M % _TILE == 0, f"M must be a multiple of {_TILE}"
        assert N % _TILE == 0, f"N must be a multiple of {_TILE}"
        assert K % _TILE == 0, f"K must be a multiple of {_TILE}"

        C = torch.empty((M, N), dtype=torch.float32, device=A.device)

        module = _get_module()

        grid = (N // _TILE, M // _TILE, 1)
        block = (_TILE // 2, _TILE // 2, 1)

        stream = torch.cuda.current_stream(device=A.device)

        module.launch(
            _KERNEL_NAME,
            grid,
            block,
            [
                u64(A_c.data_ptr()),
                u64(B_c.data_ptr()),
                u64(C.data_ptr()),
                i32(M),
                i32(N),
                i32(K),
            ],
            stream=stream,
        )

        return C
